-- PostgreSQL query. Reference CSV was generated by executing the equivalent logic on the SQLite validation DB.

WITH line_versions AS (
 SELECT l.*, h.supplier_id, h.order_dttm_msk, h.currency,
        i.category,
        ROW_NUMBER() OVER (PARTITION BY l.order_id,l.line_no ORDER BY l.updated_at DESC, l.source_row_no DESC) AS rn
 FROM core_po_line_version l
 JOIN core_po_header h ON h.order_id=l.order_id
 LEFT JOIN core_dim_item i ON i.item_id=l.item_id
 WHERE l.planned_delivery_date IS NOT NULL
),
canonical_lines AS (
 SELECT * FROM line_versions WHERE rn=1 AND lower(COALESCE(status,'')) <> 'cancelled'
),
receipt_agg AS (
 SELECT order_id,line_no,
        SUM(CASE WHEN lower(COALESCE(quality_status,''))='accepted' THEN qty_received ELSE 0 END) AS accepted_qty,
        COUNT(*) AS receipt_events,
        MAX((received_at_utc::timestamptz AT TIME ZONE 'UTC')::date) AS last_receipt_date
 FROM core_fact_receipt
 GROUP BY order_id,line_no
),
line_eval AS (
 SELECT l.order_id,l.line_no,l.supplier_id,COALESCE(s.reliability_class,'UNKNOWN') AS reliability_class,
        to_char(l.planned_delivery_date::date, 'YYYY-MM') AS planned_month,
        l.planned_delivery_date::date AS planned_delivery_date,l.qty,l.uom_code,u.base_uom,u.factor_to_base,
        COALESCE(r.accepted_qty,0) AS accepted_qty,r.receipt_events,r.last_receipt_date,
        CASE WHEN r.last_receipt_date <= l.planned_delivery_date::date
                  AND COALESCE(r.accepted_qty,0)*COALESCE(u.factor_to_base,1) >= l.qty*COALESCE(u.factor_to_base,1)
             THEN 1 ELSE 0 END AS otif
 FROM canonical_lines l
 LEFT JOIN receipt_agg r ON r.order_id=l.order_id AND r.line_no=l.line_no
 LEFT JOIN core_dim_uom u ON u.uom_code=l.uom_code
 LEFT JOIN core_supplier_version s
   ON s.supplier_id=l.supplier_id
  AND l.order_dttm_msk::date>=s.valid_from::date
  AND (s.valid_to IS NULL OR l.order_dttm_msk::date<s.valid_to::date OR s.valid_to='9999-12-31')
 WHERE l.planned_delivery_date::date >= '2026-02-01'
   AND l.planned_delivery_date::date < '2026-08-01'
),
supplier_month AS (
 SELECT supplier_id,reliability_class,planned_month,
        COUNT(*) AS line_deliveries,
        SUM(otif) AS otif_lines,
        1.0*SUM(otif)/COUNT(*) AS otif_rate
 FROM line_eval
 GROUP BY supplier_id,reliability_class,planned_month
),
eligible_suppliers AS (
 SELECT supplier_id FROM line_eval GROUP BY supplier_id HAVING SUM(COALESCE(receipt_events,0)) >= 20
)
SELECT sm.supplier_id,sm.reliability_class,sm.planned_month,sm.line_deliveries,sm.otif_lines,
       ROUND(sm.otif_rate,4) AS otif_rate,
       DENSE_RANK() OVER (PARTITION BY sm.reliability_class,sm.planned_month ORDER BY sm.otif_rate DESC) AS rank_in_reliability_class
FROM supplier_month sm JOIN eligible_suppliers e USING(supplier_id)
ORDER BY sm.planned_month,sm.reliability_class,rank_in_reliability_class,sm.supplier_id;
